export const getSelectItem = ({
  user,
  vcsUsername,
  isCurrentUser,
}: {
  user?: {id?: UserId | null} & Partial<User>
  vcsUsername?: string | null
  isCurrentUser?: boolean
}): SelectItem<UserSelectItem> => {
  const {id, avatars, name} = user ?? {}
  const avatarsMap: Record<string, string | null> | null | undefined = avatars
  const avatar = avatarsMap?.[getAvatarSizeKey(Size.Size40)]
  const username = vcsUsername ?? user?.username ?? ''

  const defaultLabel = name != null && name !== '' ? `${name} (${username})` : username
  const currentUserLabel = username != null ? `Me (${username})` : 'Me'

  return {
    key: username,
    userId: id,
    username: name ?? user?.username ?? vcsUsername,
    label: (isCurrentUser ? currentUserLabel : defaultLabel) || '<anonymous>',
    value: username,
    rgItemType: List.ListProps.Type.ITEM,
    showGeneratedAvatar: id != null,
    avatar: avatar && resolveRelative(avatar),
  }
}

export const getSelectedItem = (
  items: UserSelectData,
  selected: string | null,
): UserSelectSelectedItem => items.find(item => selected === item.value) ?? null

export const getSelectedItemByUserId = (
  items: UserSelectData,
  selected: UserId | string | null,
): UserSelectSelectedItem => items.find(item => selected === item.userId) ?? null

export const sortCommitersByName = (commiters: CommiterSelectQuery$data['changeCommiters']) =>
  [...(commiters?.commiter ?? [])].sort((a, b) => {
    const nameA = (a.users?.user?.[0]?.name || a.vcsUsername || '').toLowerCase()
    const nameB = (b.users?.user?.[0]?.name || b.vcsUsername || '').toLowerCase()

    if (nameA !== nameB) {
      return nameA > nameB ? 1 : -1
    }

    return 0
  })

export const sortUsersByName = (users: AllUserSelectQuery$data['users']) =>
  [...(users?.user ?? [])].sort((userA, userB) => {
    const nameA = (userA.name || userA.username || '').toLowerCase()
    const nameB = (userB.name || userB.username || '').toLowerCase()

    if (nameA !== nameB) {
      return nameA > nameB ? 1 : -1
    }

    return 0
  })
